mapper.select:
	explain SELECT count(1) FROM chara_trail
	where 1 = 1

        and data = #{data,jdbcType=VARCHAR}


       and remarks = #{remarks,jdbcType=VARCHAR}


        and source = #{source,jdbcType=VARCHAR}


       and chara_name = #{charaName,jdbcType=VARCHAR}


        and cid = #{cid,jdbcType=INTEGER}


        and add_time = #{addTime,jdbcType=TIMESTAMP}


      	and DATE_FORMAT(add_time,"%Y-%m-%d")>=#{startTime,jdbcType=VARCHAR}  


        and DATE_FORMAT(add_time,"%Y-%m-%d")<=#{endTime,jdbcType=VARCHAR}
